18		ReverseReservation(ctx context.Context, entitlementID, reservationID, reversalID string) (entitlements.Reservation, bool, error)
19		GetView(ctx context.Context, entitlementID string) (entitlements.View, error)
20	}
21	
22	func New(checkDatabase func(context.Context) error, service Service) http.Handler {
23		mux := http.NewServeMux()
24		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
25			respond(w, http.StatusOK, `{"status":"ok"}`)
26		})
27		mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
28			ctx, cancel := context.WithTimeout(r.Context(), time.Second)
29			defer cancel()
30			if err := checkDatabase(ctx); err != nil {
31				respond(w, http.StatusServiceUnavailable, `{"status":"unavailable"}`)
32				return
33			}
34			respond(w, http.StatusOK, `{"status":"ready"}`)
35		})
36	
37		h := &handlers{service: service}
38		mux.HandleFunc("POST /entitlements", h.createEntitlement)
39		mux.HandleFunc("GET /entitlements/{entitlementID}", h.getEntitlement)
40		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations", h.createReservation)
41		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/confirm", h.settle(entitlements.ActionConfirm))
42		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/release", h.settle(entitlements.ActionRelease))
43		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/reverse", h.reverseReservation)
44		return mux
45	}
46	
47	type handlers struct {
48		service Service
49	}
50	
51	type createEntitlementRequest struct {
52		EntitlementID string `json:"entitlement_id"`
53		SeatsTotal    *int64 `json:"seats_total"`
54		QuotaTotal    *int64 `json:"quota_total"`
55		ValidFrom     string `json:"valid_from"`
56		ValidTo       string `json:"valid_to"`
57	}
